// #031940 (6a993d6e847b25e5b0031940) «פיתוח: טיפול בתקלה טכנית ואיפוס ניסיון» — проверено 04.11.2026, «עבר QA» 04.11.
// Окно «איפוס ניסיון» у business (только валидация и отмена — реальный сброс НЕ выполняется):
//  - тех. сбой (по умолчанию QA-da072b-2110-C): после ответа get_attempt_audit_trail в окне «השלב האחרון שנרשם: …» и
//    «ההקלטה החלקית והלוג הטכני נשמרים גם אחרי האיפוס.» (реджект 1, Figma 818:1447); без причины — «יש לתעד את סיבת
//    האיפוס» (треб.3), «חזרה» закрывает окно, попытка осталась «תקלה טכנית» (скрин 031940-reset-noreason-error-business);
//  - завершённая официальная (по умолчанию QA-C8-2110-D3): галочка «אני מאשר/ת את האיפוס כאישור חריג» не отмечена →
//    «איפוס ניסיון שהושלם דורש סימון כאישור חריג» (AC4), попытка осталась «הושלמה» (скрин 031940-exc-reset-nocheck-business).
// Страховка: reset_attempt перехватывается и обрывается (guardReset) — даже при регрессии сброса не будет → @prod-safe.
// Не автоматизировано: AC1 (обрыв звонка → частичная запись/лог/статус — нужен звонок), AC3 и исключительный сброс С
// галочкой (необратимы), отметка «אופס כאישור חריג» в трассе SA (только после нового реального сброса).
import { test, expect } from '../../fixtures';
import { openWithApi } from '../support/api';
import { RESET, attemptStatus, candidateRow, guardReset, pickCandidate, resetButton, resetDialog } from './reset-support';

const HASH = '#031940 · #6a993d6e847b25e5b0031940';
const TECHFAIL = process.env.QA_RESET_TECHFAIL_CANDIDATE || 'QA-da072b-2110-C';
const COMPLETED = process.env.QA_COMPLETED_CANDIDATE || 'QA-C8-2110-D3';

test.describe(`Окно «איפוס ניסיון» — этап, обязательная причина, исключительный сброс (${HASH})`, () => {
  test(`тех. сбой: окно содержит «${RESET.lastStage} …» и «${RESET.kept}»; без причины — «${RESET.noReason}»; «${RESET.back}» — попытка не сброшена @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const hits = await guardReset(page);
    const api = await openWithApi(page, '/candidates');
    const c = await pickCandidate(api, 'technical_failure', TECHFAIL);
    test.info().annotations.push({ type: 'candidate', description: c.full_name });

    const row = await candidateRow(page, c.full_name);
    // Блок этапа приходит с сервера — ждём ответ трассы (у verifier 04.11 скрин «без блока» был снят до ответа).
    const trail = page.waitForResponse((r) => r.url().includes('/rest/v1/rpc/get_attempt_audit_trail') && r.request().method() === 'POST');
    await resetButton(row).click();
    const dialog = resetDialog(page);
    await expect(dialog).toBeVisible();
    expect((await trail).status(), 'get_attempt_audit_trail').toBe(200);

    // Источник: реджект 1 (Figma 818:1447) — инфо-блок над полем причины.
    await expect(dialog.getByText(new RegExp(`${RESET.lastStage}\\s*\\S`))).toBeVisible();
    await expect(dialog.getByText(RESET.kept)).toBeVisible();
    const stageBox = await dialog.getByText(RESET.kept).boundingBox();
    const reasonBox = await dialog.getByLabel(RESET.reason).boundingBox();
    expect(stageBox && reasonBox && stageBox.y < reasonBox.y, 'блок этапа над полем причины').toBeTruthy();

    // Источник: треб.3 «עם תיעוד חובה של סיבת האיפוס».
    await expect(dialog.getByLabel(RESET.reason)).toHaveValue('');
    await dialog.getByRole('button', { name: RESET.submit, exact: true }).click();
    await expect(dialog.getByText(RESET.noReason)).toBeVisible();
    await expect(dialog).toBeVisible();
    expect(hits, 'reset_attempt без причины').toHaveLength(0);

    await dialog.getByRole('button', { name: RESET.back, exact: true }).click();
    await expect(resetDialog(page)).toHaveCount(0);
    expect(await attemptStatus(api, c.id), 'попытка осталась в «תקלה טכנית»').toBe('technical_failure');
  });

  test(`завершённая официальная: причина есть, «${RESET.exceptional}» не отмечено → «${RESET.exceptionalRequired}»; «${RESET.back}» — попытка не сброшена @desktop @prod-safe ${HASH}`, async ({ asUser }) => {
    const page = await asUser('business');
    const hits = await guardReset(page);
    const api = await openWithApi(page, '/candidates');
    const c = await pickCandidate(api, 'completed', COMPLETED);
    test.info().annotations.push({ type: 'candidate', description: c.full_name });

    const row = await candidateRow(page, c.full_name);
    await resetButton(row).click();
    const dialog = resetDialog(page);
    await expect(dialog).toBeVisible();
    await expect(dialog.getByText(/הניסיון הרשמי הושלם/)).toBeVisible();
    const exceptional = dialog.getByLabel(RESET.exceptional);
    await expect(exceptional).toBeVisible();
    await expect(exceptional).not.toBeChecked();

    await dialog.getByLabel(RESET.reason).fill('QA-AUTO-031940 בדיקת אישור חריג — לא לבצע');
    await dialog.getByRole('button', { name: RESET.submit, exact: true }).click();
    // Источник: AC4 «איפוס ניסיון שהושלם… הפעולה דורשת סימון כאישור חריג».
    await expect(dialog.getByText(RESET.exceptionalRequired)).toBeVisible();
    await expect(dialog).toBeVisible();
    await expect(exceptional).not.toBeChecked();
    test.info().annotations.push({ type: 'reset_attempt calls (оборваны)', description: String(hits.length) });

    await dialog.getByRole('button', { name: RESET.back, exact: true }).click();
    await expect(resetDialog(page)).toHaveCount(0);
    expect(await attemptStatus(api, c.id), 'попытка осталась «completed»').toBe('completed');
  });
});
